const SCRIPT = "\n  (function () {\n    var reduce = window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n    var tour = document.getElementById(\"tour\");\n    var phones = document.getElementById(\"phones\");\n    var bodies = [].slice.call(document.querySelectorAll(\"[data-body]\"));\n    var steps = [].slice.call(document.querySelectorAll(\".step\"));\n    var tourDone = document.getElementById(\"tourDone\");\n    var prevBtn = document.getElementById(\"prev\");\n    var nextBtn = document.getElementById(\"next\");\n    var playBtn = document.getElementById(\"play\");\n    var TOTAL = 5, STEPDUR = 3200, HOLD = 2200;\n    var cur = 1, playing = false, timer = null;\n\n    if (tour) tour.style.setProperty(\"--stepdur\", STEPDUR + \"ms\");\n\n    function revealTour(n, animate) {\n      document.querySelectorAll(\".b[data-tour]\").forEach(function (el) {\n        var show = (+el.getAttribute(\"data-tour\")) <= n;\n        var wasHidden = el.classList.contains(\"hide\");\n        el.classList.toggle(\"hide\", !show);\n        el.classList.remove(\"reveal\");\n        if (show && wasHidden && animate) { void el.offsetWidth; el.classList.add(\"reveal\"); }\n      });\n      bodies.forEach(function (b) {\n        var prev = b.style.scrollBehavior;\n        b.style.scrollBehavior = animate ? \"smooth\" : \"auto\";\n        b.scrollTop = b.scrollHeight;\n        b.style.scrollBehavior = prev;\n      });\n    }\n\n    function paint() {\n      steps.forEach(function (li) {\n        var t = +li.getAttribute(\"data-tour\");\n        li.classList.toggle(\"is-active\", t === cur);\n        li.classList.toggle(\"is-done\", t < cur);\n        li.classList.toggle(\"is-playing\", t === cur && playing);\n      });\n      if (tourDone) tourDone.hidden = (cur !== TOTAL);\n    }\n\n    function setStep(n, animate) {\n      cur = n < 1 ? 1 : (n > TOTAL ? TOTAL : n);\n      paint();\n      revealTour(cur, animate);\n    }\n\n    function schedule() {\n      clearTimeout(timer);\n      if (!playing) return;\n      var dur = (cur === TOTAL) ? (STEPDUR + HOLD) : STEPDUR;\n      timer = setTimeout(function () {\n        setStep(cur >= TOTAL ? 1 : cur + 1, true);\n        schedule();\n      }, dur);\n    }\n\n    function play() {\n      if (reduce) return;\n      playing = true;\n      playBtn.classList.remove(\"paused\");\n      playBtn.setAttribute(\"aria-label\", \"Pause demo\");\n      paint();\n      schedule();\n    }\n    function pause() {\n      playing = false;\n      clearTimeout(timer);\n      playBtn.classList.add(\"paused\");\n      playBtn.setAttribute(\"aria-label\", \"Play demo\");\n      paint();\n    }\n\n    prevBtn.addEventListener(\"click\", function () { setStep(cur - 1, true); if (playing) schedule(); });\n    nextBtn.addEventListener(\"click\", function () { setStep(cur >= TOTAL ? 1 : cur + 1, true); if (playing) schedule(); });\n    playBtn.addEventListener(\"click\", function () { playing ? pause() : play(); });\n    steps.forEach(function (li) {\n      li.setAttribute(\"tabindex\", \"0\");\n      li.addEventListener(\"click\", function () { setStep(+li.getAttribute(\"data-tour\"), true); if (playing) schedule(); });\n      li.addEventListener(\"keydown\", function (e) { if (e.key === \"Enter\" || e.key === \" \") { e.preventDefault(); li.click(); } });\n    });\n\n    if (reduce) {\n      document.querySelectorAll(\".b[data-tour]\").forEach(function (el) { el.classList.remove(\"hide\"); });\n      cur = TOTAL; paint();\n      bodies.forEach(function (b) { b.scrollTop = b.scrollHeight; });\n      playBtn.classList.add(\"paused\");\n      return;\n    }\n\n    setStep(1, false);\n    playBtn.classList.add(\"paused\");\n\n    if (\"IntersectionObserver\" in window) {\n      var seen = false;\n      var io = new IntersectionObserver(function (entries) {\n        entries.forEach(function (e) {\n          if (e.isIntersecting) { if (!seen) { seen = true; play(); } else if (playing) { schedule(); } }\n          else { clearTimeout(timer); }\n        });\n      }, { threshold: 0.3 });\n      io.observe(phones);\n    } else { play(); }\n  })();\n";

export default function ChatDemo() {
  const ref = useRef<HTMLDivElement>(null);
  const ran = useRef(false);
  useEffect(() => {
    if (ran.current) return;
    ran.current = true;
    try { new Function(SCRIPT)(); } catch (e) { console.error("ChatDemo demo:", e); }
  }, []);
  return (
    <div ref={ref} className="cpc-chat"
      dangerouslySetInnerHTML={{ __html: "<style>" + CSS + "</style>" + MARKUP }} />
  );
}
